<?php require __DIR__.'/app/bootstrap.php';$products=query('SELECT p.*,EXISTS(SELECT 1 FROM variants v WHERE v.product_id=p.id AND (v.stock IS NULL OR v.stock>0)) AS available FROM products p WHERE active=1 ORDER BY available DESC,created_at DESC,id DESC')->fetchAll();$categories=['T-shirts','Hoodies','Lowers'];$counts=[];
foreach($products as &$product){$category=trim($product['category']??'');if(strcasecmp($category,'Cargo Pants')===0)$category='Lowers';if(strcasecmp($category,'T-Shirts')===0)$category='T-shirts';$product['category']=$category;if($category!==''){if(!in_array($category,$categories,true))$categories[]=$category;$counts[$category]=($counts[$category]??0)+1;}}unset($product);
$selected=is_string($_GET['category']??null)?$_GET['category']:'';
if(!in_array($selected,$categories,true))$selected='';
$total=count($products);if($selected!=='')$products=array_values(array_filter($products,fn($p)=>$p['category']===$selected));
$GLOBALS['storefront_theme']=true;render_header('Street culture. Your way.'); ?>
