<div class="ticker" aria-hidden="true"><span>FLAWED URBANWEAR</span> ✦ <span>WEAR YOUR OWN STORY</span> ✦ <span>STREET CULTURE / EST. 2023</span> ✦</div>
<section class="shop" id="shop"><h2 class="shop-heading">Shop the collection</h2><nav class="shop-categories" aria-label="Shop categories"><a href="<?=url('index.php#shop')?>" <?=$selected===''?'aria-current="page"':''?>>All <small><?=$total?></small></a><?php foreach($categories as $category):?><a href="<?=url('index.php?category='.rawurlencode($category).'#shop')?>" <?=$selected===$category?'aria-current="page"':''?>><?=h($category)?> <small><?=$counts[$category]??0?></small></a><?php endforeach ?></nav><p class="catalog-count" role="status"><?=count($products)?> <?=count($products)===1?'product':'products'?><?= $selected!==''?' in '.h($selected):' in the collection'?></p><div class="catalog">
